  public ContainerDiffReport diff(KeyValueContainerData thisContainer,
      ContainerProtos.ContainerChecksumInfo peerChecksumInfo) throws StorageContainerException {
    ContainerDiffReport report = new ContainerDiffReport();
    long containerID = thisContainer.getContainerID();
    try {
      Optional<ContainerProtos.ContainerChecksumInfo.Builder> thisChecksumInfoBuilder = read(thisContainer);
      if (!thisChecksumInfoBuilder.isPresent()) {
        throw new StorageContainerException("Container #" + containerID +
            " does not have a checksum file to diff against its peer.", ContainerProtos.Result.CONTAINER_CHECKSUM_ERROR);
      }
      ContainerProtos.ContainerChecksumInfo thisChecksumInfo = thisChecksumInfoBuilder.get().build();

      if (thisChecksumInfo.getContainerID() != peerChecksumInfo.getContainerID()) {
        throw new StorageContainerException("Container ID does not match. Local container ID "
